            // Execution will never reach here unless the transfer fails
            System.out.println("Returned unexpectedly!");

        } catch (Throwable t) {           // Catch both checked & unchecked errors
            System.err.printf(
                "[ERROR] Failed to switch coroutines (%d→%d): %s%n",
                CURRENT_CORO_ID, TARGET_CORO_ID, t.getMessage());
